/// <summary>
/// Extension class for the "Order Remove" button control in the Unit of Measure Conversion Edit or Create form.
/// </summary>
[ExtensionOf(formControlStr(UnitOfMeasureConversionEditOrCreate, AVARUMOrderRemoveButton))]
internal final class AVARUMUnitOfMeasureConversionEditOrCreate_AVARUMOrderRemoveButtonCtrl_Extension
{
}

Method.Source:
/// <summary>
/// Handles the click event for the "Order Remove" button.
/// </summary>
public void clicked()
{
    FormButtonControl buttonRemoveControl;
    FormRun formRun;
    FormDataSource formDataSource;
    UnitOfMeasureConversion unitOfMeasureConversion;

    next clicked();

    buttonRemoveControl = Global::any2Object(this) as FormButtonControl;
    formRun = buttonRemoveControl.formRun();
    formDataSource = formRun.dataSource(formDataSourceStr(UnitOfMeasureConversionEditOrCreate, UnitOfMeasureConversion));
    unitOfMeasureConversion = formDataSource.cursor();
    unitOfMeasureConversion.changeOrder_AVA(false, true);

    element.isUnitOrderChanged_AVA(true);
}
